// Parse a Valley (example.com) webhook into the Raw Valley Events shape.
// Real payload structure (confirmed from live test):
//   { event_type, timestamp, user{sender}, prospect{name,company_name,linkedin_url,title,industry,location},
//     campaign{name,template_name,type}, message{content,sender}, conversation{id,medium},
//     interest_level, tag... }
const body = $json.body || $json;
const p   = body.prospect || {};
const camp= body.campaign || {};
const msg = body.message || {};
const conv= body.conversation || {};

const eventType = body.event_type || 'event';
const ts = body.timestamp || msg.timestamp || new Date().toISOString();
const linkedin = p.linkedin_url || '';
const msgId = msg.message_id || conv.id || '';

// Unique Event ID per event (dedupe key for upsert)
const eventId = msgId
  ? (eventType + '|' + msgId)
  : (eventType + '|' + (p.id || linkedin || 'unknown') + '|' + ts);

// Tag name (only present on Tag Changed events; shape may vary)
const tagName = body.tag || body.tag_name ||
  (body.tag_changed && (body.tag_changed.name || body.tag_changed.tag)) ||
  (Array.isArray(body.tags) ? body.tags.join(', ') : '') || '';

return [{ json: {
  'Event ID':          eventId,
  'Prospect Name':     p.name || '',
  'Prospect Email':    p.email || '',                 // Valley LinkedIn rarely has email
  'Prospect LinkedIn': linkedin,
  'Prospect Company':  p.company_name || p.company || '',
  'Prospect Title':    p.title || '',
  'Event Type':        eventType,
  'Interest Level':    body.interest_level || '',
  'Tag Name':          tagName,
  'Response Text':     msg.content || body.response || '',
  'Campaign Name':     camp.name || '',
  'Message Medium':    conv.medium || (camp.type || ''),
  'Valley Timestamp':  ts,
  'Raw Payload':       JSON.stringify(body)
}}];
